 private static java.util.List<CompoundTag> deferredOwnership(){java.util.List<CompoundTag> result=new java.util.ArrayList<>();CompoundTag owned=new CompoundTag(),reader=new CompoundTag(),item=new CompoundTag();item.putString("id","vandorlabs:data_chip");item.putByte("Count",(byte)1);item.putShort("Damage",(short)2);item.putString("PrivateJournal","retained");reader.put("InsertedToken",item);owned.put("ScreenChipReader",reader);result.add(owned);CompoundTag malformed=new CompoundTag();malformed.putString("ScreenChipReader","future ownership envelope");result.add(malformed);CompoundTag unknown=new CompoundTag(),future=new CompoundTag();future.putString("FutureOwner","opaque");unknown.put("ScreenChipReader",future);result.add(unknown);for(String key:new String[]{"PrimarySurfaceTexture","SecondarySurfaceTexture"})for(int surface:new int[]{-4,-3}){CompoundTag selected=new CompoundTag();selected.putInt(key,surface);result.add(selected);}return result;}
 private static BlockPos ownershipPosition(int index){return INERT.south(2+index);}
 private static void platformDeletion(ServerLevel world){var pos=POS.south(8);world.setBlock(pos,block.defaultBlockState(),2);var tile=host(world,pos);var data=new CompoundTag();var persistent=new CompoundTag();persistent.putString("Original","delete");data.put("NeoForgeData",persistent);var attached=new CompoundTag();attached.putString("vandorlabs:screen_host_attachment","delete");data.put("neoforge:attachments",attached);var components=new CompoundTag();components.putString("minecraft:custom_name","\"Original\"");data.put("components",components);data.putString("ForeignRoot","retain");var original=data.copy();tile.loadWithComponents(data,world.registryAccess());need(!tile.inert()&&tile.getData(attachment).equals("delete"),"actual platform data installed");tile.getPersistentData().remove("Original");tile.removeData(attachment);tile.setComponents(net.minecraft.core.component.DataComponentMap.EMPTY);var saved=tile.saveWithoutMetadata(world.registryAccess());need(!saved.contains("components")&&!saved.getCompound("NeoForgeData").contains("Original")&&!saved.getCompound("neoforge:attachments").contains("vandorlabs:screen_host_attachment"),"live platform deletions cannot resurrect retained originals");need(data.equals(original)&&saved.getString("ForeignRoot").equals("retain"),"platform load input and unrelated private bytes preserved");data.putInt("ScreenChipReader",42);original=data.copy();tile.loadWithComponents(data,world.registryAccess());tile.getPersistentData().putBoolean("PartialLive",true);need(tile.inert()&&tile.saveWithoutMetadata(world.registryAccess()).equals(original),"inert ownership failure retains complete original platform envelope");world.removeBlock(pos,false);}
 private static void ownership(ServerLevel world){for(CompoundTag empty:java.util.List.of(new CompoundTag(),emptyReader())){CompoundTag saved=new CompoundTag();saved.put("ScreenChipReader",empty);saved.putString("Unrelated","private");world.setBlock(ownershipPosition(8),block.defaultBlockState(),2);NativeScreenEntity host=host(world,ownershipPosition(8));host.loadWithComponents(saved,world.registryAccess());need(!host.inert()&&host.saveWithoutMetadata(world.registryAccess()).get("ScreenChipReader").equals(empty),"provably empty reader remains installable and exact private envelope retained");need(!host.getUpdateTag(world.registryAccess()).contains("ScreenChipReader"),"empty reader envelope excluded from public DTO");}var cases=deferredOwnership();for(int i=0;i<cases.size();i++){world.setBlock(ownershipPosition(i),block.defaultBlockState(),2);var host=host(world,ownershipPosition(i));host.loadWithComponents(cases.get(i),world.registryAccess());need(host.inert()&&!host.isChannelMemberActive()&&host.localOutput()==0,"deferred reader/selected surface remains inert "+i);need(host.saveWithoutMetadata(world.registryAccess()).equals(cases.get(i)),"original deferred ownership saved unchanged "+i);need(!host.getUpdateTag(world.registryAccess()).contains("ScreenChipReader"),"private ownership not projected "+i);}}
 private static CompoundTag emptyReader(){CompoundTag tag=new CompoundTag();tag.putBoolean("AnyToken",true);tag.putInt("AllowedTokens",127);tag.putBoolean("ChipSlot",true);tag.putInt("TokenLogo",0);tag.putInt("TokenBehavior",0);for(String key:new String[]{"TokenPulseUntil","TokenInsertStarted","TokenRejectedUntil","TokenInsertionSequence"})tag.putLong(key,0);tag.putBoolean("TokenToggleApplied",false);tag.putBoolean("TokenToggled",false);return tag;}
 private static CompoundTag withoutWorldIdentity(CompoundTag tag){for(String key:new String[]{"id","x","y","z","keepPacked"})tag.remove(key);return tag;}
 private static void verifyOwnership(ServerLevel world){var cases=deferredOwnership();for(int i=0;i<cases.size();i++){var host=host(world,ownershipPosition(i));need(host!=null&&host.inert()&&!host.isChannelMemberActive()&&withoutWorldIdentity(host.saveWithoutMetadata(world.registryAccess())).equals(cases.get(i)),"actual restart retains sole opaque ownership and selected surface "+i+" actual="+(host==null?"missing":host.saveWithoutMetadata(world.registryAccess())));}var empty=host(world,ownershipPosition(8));need(empty!=null&&!empty.inert()&&empty.saveWithoutMetadata(world.registryAccess()).getCompound("ScreenChipReader").equals(emptyReader()),"actual restart accepts canonical empty reader without losing its envelope");}
 private static int packetBytes(ServerLevel world,NativeScreenEntity owner,CompoundTag tag){var bytes=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),world.registryAccess());try{var packet=net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket.create(owner,(tile,registries)->tag.copy());net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket.STREAM_CODEC.encode(bytes,packet);int count=bytes.readableBytes();var decoded=net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket.STREAM_CODEC.decode(bytes);need(!bytes.isReadable()&&decoded.getPos().equals(owner.getBlockPos())&&decoded.getType()==owner.getType()&&decoded.getTag().equals(tag),"real block-entity packet codec roundtrip");return count;}finally{bytes.release();}}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.LevelTickEvent.Post event){if(event.getLevel()!=pendingRead||++readTicks<5)return;ServerLevel world=pendingRead;if(!checkedRestart){verifyRead(world);need(NativeRedstoneChannels.level(world,SAVE,73102)==15&&NativeRedstoneChannels.level(world,SAVE,73103)==15,"actual restart resumes remaining pulse and independent toggle");checkedRestart=true;}if(world.getGameTime()<=200)return;need(NativeRedstoneChannels.level(world,SAVE,73102)==0&&NativeRedstoneChannels.level(world,SAVE,73103)==15,"actual post-restart level ticks expire pulse without clearing independent toggle");need(host(world,SAVE).controls(0).rows().get(0).pulseUntil()==0&&NativeScreenControlService.activeCount(world)==0,"expired services leave the active-only queue");pendingRead=null;observing=false;System.out.println("[vandorlabs][screen-host] read PASS checks="+checks+" actual chunk onLoad/deferred channels plus remaining pulse expiry/independent toggle/idle queue");world.getServer().halt(false);}
 private static void verifyRead(ServerLevel world){verifyOwnership(world);NativeScreenEntity restored=host(world,SAVE);need(restored!=null&&!restored.inert()&&restored.screenSettings().channels().equals(ChannelList.of(73101))&&restored.controls(0).rows().get(0).pulseUntil()==200,"actual process restart restores screen/control choices");CompoundTag saved=restored.saveWithoutMetadata(world.registryAccess());need(saved.getString("ForeignRoot").equals("retained")&&saved.getCompound("ForgeCaps").getString("ExternalOwner").equals("opaque")&&saved.getString("DisplayActivation").equals("future activation envelope"),"restart retains opaque envelope");need(host(world,INERT).inert()&&host(world,INERT).saveWithoutMetadata(world.registryAccess()).getString("UnknownFuture").equals("retained"),"actual restart preserves inert failed snapshot");NativeRedstoneChannels.flush(world);need(restored.visual().effectivePower()==7,"restart samples physical power only after deferred flush");
 }
